(7289894, 1136179, 13077, '<td valign="top">Very colorful and visually pleasing. Good use of the square window for framing.</td>', 'Very colorful and visually pleasing. Good use of the square window for framing.', '2014-12-04 19:26:34.000000', NULL, 1),
