(7289905, 1136156, 13077, '<td valign="top">Excellent details in the road and underside of the bridge, and just enough detail in the bright background. Very strong composition as well.</td>', 'Excellent details in the road and underside of the bridge, and just enough detail in the bright background. Very strong composition as well.', '2014-12-04 19:35:08.000000', NULL, 1),
(7289906, 1136147, 13077, '<td valign="top">Nice - very well composed, fascinating that they have the same jacket, and their position in the frame jives well with the rest of the elements.</td>', 'Nice - very well composed, fascinating that they have the same jacket, and their position in the frame jives well with the rest of the elements.', '2014-12-04 19:35:45.000000', NULL, 1),
(7289907, 1136165, 13077, '<td valign="top">Not a fan of this one - tough to tell if it''s concrete so maybe a little too far on the abstract side for my taste.</td>', 'Not a fan of this one - tough to tell if it''s concrete so maybe a little too far on the abstract side for my taste.', '2014-12-04 19:36:19.000000', NULL, 1),
(7289908, 1136064, 13077, '<td valign="top">Very cool looking sky, and good detail in the concrete garage. Well composed as well.</td>', 'Very cool looking sky, and good detail in the concrete garage. Well composed as well.', '2014-12-04 19:36:49.000000', NULL, 1),
(7289909, 1136150, 13077, '<td valign="top">Beautiful sky and light. Looks like a fascinating place, and perfect for the challenge. My top pick so far.</td>', 'Beautiful sky and light. Looks like a fascinating place, and perfect for the challenge. My top pick so far.', '2014-12-04 19:37:23.000000', NULL, 1),
